gcM(){return"\u10d2\u10d0\u10db\u10dd\u10e7\u10d4\u10dc\u10d4\u10d1\u10d8\u10e1 \u10de\u10d8\u10e0\u10dd\u10d1\u10d4\u10d1\u10d8"},
gc3(){return"\u10e9\u10d0\u10db\u10dd\u10e2\u10d5\u10d8\u10e0\u10d7\u10d5\u10d0 Android-\u10d8\u10e1\u10d7\u10d5\u10d8\u10e1"},
gc4(){return"\u10e9\u10d0\u10db\u10dd\u10e2\u10d5\u10d8\u10e0\u10d7\u10d5\u10d0 iOS-\u10d8\u10e1\u10d7\u10d5\u10d8\u10e1"},
gc8(){return"\u10e9\u10d0\u10db\u10dd\u10e2\u10d5\u10d8\u10e0\u10d7\u10d5\u10d0 macOS-\u10d8\u10e1\u10d7\u10d5\u10d8\u10e1"},
gdk(){return"\u10e0\u10dd\u10d2\u10dd\u10e0 \u10db\u10e3\u10e8\u10d0\u10dd\u10d1\u10e1 AI \u10de\u10e0\u10d0\u10e5\u10e2\u10d8\u10d9\u10d8\u10e1 \u10e0\u10d4\u10de\u10d4\u10e2\u10d8\u10e2\u10dd\u10e0\u10d8?"},
gd9(){return"\u10e8\u10d4\u10d2\u10d8\u10eb\u10da\u10d8\u10d0\u10d7 \u10d2\u10d0\u10db\u10d0\u10e0\u10d7\u10dd\u10d7 \u10ee\u10db\u10dd\u10d5\u10d0\u10dc\u10d8 \u10e1\u10d0\u10e3\u10d1\u10e0\u10d4\u10d1\u10d8 \u10e0\u10d4\u10d0\u10da\u10e3\u10e0 \u10d3\u10e0\u10dd\u10e8\u10d8 \u10dc\u10d4\u10d1\u10d8\u10e1\u10db\u10d8\u10d4\u10e0 \u10d7\u10d4\u10db\u10d0\u10d6\u10d4 \u10e1\u10ee\u10d5\u10d0\u10d3\u10d0\u10e1\u10ee\u10d5\u10d0 \u10d3\u10dd\u10dc\u10d4\u10d6\u10d4. AI \u10d2\u10d0\u10ec\u10d5\u10d3\u10d8\u10d7 \u10db\u10e7\u10d8\u10e1\u10d8\u10d4\u10e0 \u10e3\u10d9\u10e3\u10d9\u10d0\u10d5\u10e8\u10d8\u10e0\u10e1 \u10d7\u10e5\u10d5\u10d4\u10dc\u10e1 \u10d2\u10d0\u10d2\u10d4\u10d1\u10d0\u10d6\u10d4, \u10d2\u10e0\u10d0\u10db\u10d0\u10e2\u10d8\u10d9\u10d0\u10e1\u10d0 \u10d3\u10d0 \u10da\u10d4\u10e5\u10e1\u10d8\u10d9\u10d0\u10d6\u10d4."},
gdl(){return"\u10e8\u10d4\u10d0\u10e1\u10ec\u10dd\u10e0\u10d4\u10d1\u10e1 \u10d7\u10e3 \u10d0\u10e0\u10d0 AI \u10e9\u10d4\u10db\u10e1 \u10e8\u10d4\u10ea\u10d3\u10dd\u10db\u10d4\u10d1\u10e1 \u10e1\u10d0\u10e3\u10d1\u10e0\u10d8\u10e1\u10d0\u10e1?"},
gda(){return"\u10d3\u10d8\u10d0\u10ee. AI \u10dc\u10d0\u10d6\u10d0\u10d3 \u10d0\u10e1\u10ec\u10dd\u10e0\u10d4\u10d1\u10e1 \u10d7\u10e5\u10d5\u10d4\u10dc\u10e1 \u10d2\u10e0\u10d0\u10db\u10d0\u10e2\u10d8\u10d9\u10d0\u10e1\u10d0 \u10d3\u10d0 \u10da\u10d4\u10e5\u10e1\u10d8\u10d9\u10d0\u10e1 \u10e0\u10d4\u10d0\u10da\u10e3\u10e0 \u10d3\u10e0\u10dd\u10e8\u10d8, \u10e0\u10d0\u10d7\u10d0 \u10e1\u10e2\u10e0\u10d4\u10e1\u10d8\u10e1 \u10d2\u10d0\u10e0\u10d4\u10e8\u10d4 \u10e8\u10d4\u10d8\u10eb\u10d8\u10dc\u10dd\u10d7 \u10e1\u10d0\u10e3\u10d1\u10e0\u10d8\u10e1 \u10d3\u10d0\u10e0\u10ec\u10db\u10e3\u10dc\u10d4\u10d1\u10e3\u10da\u10dd\u10d1\u10d0."},
gdm(){return"\u10d0\u10e0\u10d8\u10e1 \u10d7\u10e3 \u10d0\u10e0\u10d0 Edhomy AI Languages \u10e3\u10e4\u10d0\u10e1\u10dd?"},
gdc(){return"\u10d0\u10de\u10da\u10d8\u10d9\u10d0\u10ea\u10d8\u10d8\u10e1 \u10e9\u10d0\u10db\u10dd\u10e2\u10d5\u10d8\u10e0\u10d7\u10d5\u10d0 \u10e3\u10e4\u10d0\u10e1\u10dd\u10d0 \u10d3\u10d0 \u10db\u10dd\u10d8\u10ea\u10d0\u10d5\u10e1 \u10e7\u10dd\u10d5\u10d4\u10da\u10d3\u10e6\u10d8\u10e3\u10e0 \u10de\u10e0\u10d0\u10e5\u10e2\u10d8\u10d9\u10e3\u10da \u10d8\u10dc\u10e1\u10e2\u10e0\u10e3\u10db\u10d4\u10dc\u10e2\u10d4\u10d1\u10e1. AI-\u10d7\u10d0\u10dc \u10e3\u10da\u10d8\u10db\u10d8\u10e2\u10dd \u10e1\u10d0\u10e3\u10d1\u10e0\u10d8\u10e1 \u10de\u10e0\u10d0\u10e5\u10e2\u10d8\u10d9\u10d0 \u10d3\u10d0 \u10d5\u10d8\u10d3\u10d4\u10dd \u10d2\u10d0\u10d9\u10d5\u10d4\u10d7\u10d8\u10da\u10d4\u10d1\u10d8 \u10db\u10dd\u10d8\u10d7\u10ee\u10dd\u10d5\u10e1 \u10de\u10e0\u10d4\u10db\u10d8\u10e3\u10db \u10d0\u10dc\u10d2\u10d0\u10e0\u10d8\u10e8\u10e1."},
